{"name":"USGS datasets","status":200,"data":[{"title":"US Topo","sbDatasetTag":"US Topo","parentCategory":"Map","id":"us-topo-main","description":"Layered GeoPDF 7.5 Minute Quadrangle Map. Layers of geospatial data include orthoimagery, roads, grids, geographic names, elevation contours, hydrography, and other selected map features. This map depicts geographic features on the surface of the earth. One intended purpose is to support emergency response at all levels of government. The geospatial data in this map are from selected National Map data holdings and other government sources.","refreshCycle":"Daily","lastPublishedDate":"Sep 4, 2019","lastUpdatedDate":"Sep 7, 2019","dataGovUrl":"https://catalog.data.gov/dataset/usgs-us-topo-map-collection","infoUrl":"https://www.sciencebase.gov/catalog/item/4f554236e4b018de15819c85","thumbnailUrl":"https://prd-tnm.s3.amazonaws.com/StagedProducts/Collections/Browse/map_ustopo_browse.jpg","mapServerLayerIdsForLegend":[2],"mapServerUrl":"https://index.nationalmap.gov/arcgis/rest/services/USTopoAvailability/MapServer","showMapServerLink":true,"mapServerLinkShowTitle":"Show Availability","mapServerLinkHideTitle":"Hide Availability","formats":[{"displayName":"Geospatial PDF","value":"GeoPDF,GeospatialPDF,Geospatial PDF","isDefault":true}],"defaultExtent":"7.5 x 7.5 minute","tags":[{"title":"US Topo Current","sbDatasetTag":"US Topo Current","id":"us-topo-curent","refreshCycle":"Undetermined","lastPublishedDate":"Sep 4, 2019","lastUpdatedDate":"Sep 7, 2019","isChecked":true,"dataGovUrl":"","infoUrl":"https://www.sciencebase.gov/catalog/item/4f554236e4b018de15819c85","thumbnailUrl":"https://prd-tnm.s3.amazonaws.com/StagedProducts/Collections/Browse/map_ustopo_browse.jpg","extents":["7.5 x 7.5 minute"]},{"title":"US Topo Non-Current","sbDatasetTag":"US Topo Historical","id":"us-topo-non-current","refreshCycle":"Undetermined","lastPublishedDate":"Jul 12, 2019","lastUpdatedDate":"Sep 7, 2019","isChecked":false,"dataGovUrl":"https://www.s