commandLine.original:
@'
const targets = [
 ['NRCan alternate STAC', 'https://datacube.services.geo.ca/stac/api/collections'],
 ['NRCan LiDAR record', 'https://open.canada.ca/data/api/action/package_show?id=7069387e-9986-4297-9f55-0288e9676947'],
 ['NRCan HRDEM record', 'https://open.canada.ca/data/api/action/package_show?id=957782bf-847c-4644-a757-e383c0057995'],
 ['NRCan HRDEM directory', 'https://ftp.maps.canada.ca/pub/elevation/dem_mne/highresolution_hauteresolution/']
];
for (const [name,url] of targets) {
 try { const response=await fetch(url,{signal:AbortSignal.timeout(45000)}); const text=await response.text(); if(name.includes('directory')){const {load}=await import('cheerio'); const page=load(text); console.log(name,response.status,JSON.stringify(page('a[href]').map((index,element)=>page(element).attr('href')).get(),null,2)); continue;} const body=JSON.parse(text); console.log(name,response.status,JSON.stringify(body.collections ? body.collections.filter(item=>/elev|dem|lidar|terrain/i.test(item.id+' '+item.title)).map(item=>({id:item.id,title:item.title})) : {success:body.success,resources:body.result?.resources?.map(item=>({name:item.name,url:item.url,format:item.format}))},null,2)); } catch(error){console.log(name,error.message,error.cause?.code);}
}
'@ | node --input-type=module

