import { area, bbox, bboxPolygon, booleanIntersects, buffer, difference, intersect, feature, featureCollection } from '@turf/turf';

export class HttpError extends Error {
  constructor(status, message, details) {
    super(message);
    this.status = status;
    this.details = details;
  }
}

export function parseBbox(input) {
  const values = typeof input === 'string' ? input.split(',').map(Number)
    : Array.isArray(input) ? input.map(Number)
      : input && [input.minLng ?? input.west ?? input.minX, input.minLat ?? input.south ?? input.minY, input.maxLng ?? input.east ?? input.maxX, input.maxLat ?? input.north ?? input.maxY].map(Number);
  if (!values || values.length !== 4 || !values.every(Number.isFinite)) {
    throw new HttpError(400, 'bbox must contain west,south,east,north in WGS84 longitude/latitude.');
  }
  const [west, south, east, north] = values;
  if (west < -180 || east > 180 || south < -90 || north > 90 || west >= east || south >= north) {
    throw new HttpError(400, 'Invalid bbox. Split antimeridian-crossing requests into separate boundaries.');
  }
  return values;
}

export function normalizeBoundary(input, defaultBuffer = 0) {
  let boundary;
  if (input.boundary) {
    boundary = input.boundary.type === 'Feature' ? structuredClone(input.boundary) : feature(input.boundary);
    if (!['Polygon', 'MultiPolygon'].includes(boundary.geometry?.type)) {
      throw new HttpError(400, 'boundary must be a WGS84 GeoJSON Polygon or MultiPolygon.');
    }
    const rings = boundary.geometry.type === 'Polygon' ? boundary.geometry.coordinates : boundary.geometry.coordinates.flat();
    let points = 0;
    for (const ring of rings) {
      if (!Array.isArray(ring) || ring.length < 4 || JSON.stringify(ring[0]) !== JSON.stringify(ring.at(-1))) {
        throw new HttpError(400, 'GeoJSON polygon rings must be closed and contain at least four coordinates.');
      }
      for (const coordinate of ring) {
        if (!Array.isArray(coordinate) || coordinate.length < 2 || !coordinate.slice(0, 2).every(Number.isFinite)
          || Math.abs(coordinate[0]) > 180 || Math.abs(coordinate[1]) > 90) {
          throw new HttpError(400, 'GeoJSON coordinates must be numeric WGS84 longitude/latitude.');
        }
        if (++points > 100000) throw new HttpError(400, 'Boundary exceeds 100,000 coordinates.');
      }
    }
  } else {
    boundary = bboxPolygon(parseBbox(input.bbox));
  }
  const bufferMeters = Number(input.bufferMeters ?? defaultBuffer);
  if (!Number.isFinite(bufferMeters) || bufferMeters < 0 || bufferMeters > 10000) {
    throw new HttpError(400, 'bufferMeters must be between 0 and 10,000.');
  }
  const queryBoundary = bufferMeters ? buffer(boundary, bufferMeters, { units: 'meters' }) : boundary;
  const extent = parseBbox(bbox(queryBoundary));
  return { boundary, queryBoundary, bbox: extent, bufferMeters, areaKm2: area(queryBoundary) / 1000000 };
}

export function intersectsBoundary(asset, query) {
  if (!asset.bbox && !asset.geometry) return false;
  const geometry = asset.geometry ? feature(asset.geometry) : bboxPolygon(parseBbox(asset.bbox));
  return booleanIntersects(geometry, query.queryBoundary);
}

export function selectAssets(assets, query, options = {}) {
  const products = options.products?.length ? options.products : null;
  const filtered = assets.filter((asset) => intersectsBoundary(asset, query)
    && (!products || products.includes(asset.product))
    && (!options.formats?.length || options.formats.includes(asset.extension))
    && (!options.collectionIds?.length || options.collectionIds.includes(asset.collectionId)));
  const resolution = options.resolution ?? 'all';
  if (resolution === 'best') {
    const groups = new Map();
    const rank = (asset) => asset.resolutionMeters || (asset.angularResolution ? asset.angularResolution * 111320 / 3600 : null);
    for (const asset of filtered) {
      const key = `${asset.sourceId}:${asset.product}`;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(asset);
    }
    return filtered.filter((asset) => {
      if (!rank(asset)) return true;
      const finer = groups.get(`${asset.sourceId}:${asset.product}`).filter((other) => rank(other) && rank(other) < rank(asset) && intersectsBoundary(other, { queryBoundary: asset.geometry ? feature(asset.geometry) : bboxPolygon(asset.bbox) }));
      if (!finer.length) return true;
      const shape = asset.geometry ? feature(asset.geometry) : bboxPolygon(asset.bbox);
      const clipped = intersect(featureCollection([shape, query.queryBoundary]));
      if (!clipped) return true;
      return difference(featureCollection([clipped, ...finer.map((other) => other.geometry ? feature(other.geometry) : bboxPolygon(other.bbox))])) !== null;
    });
  }
  if (resolution === 'all' || resolution === 'native') return filtered;
  const numeric = Number(resolution);
  if (!(numeric > 0) || !Number.isFinite(numeric)) throw new HttpError(400, 'resolution must be best, all, native, or a positive number in meters.');
  return filtered.filter((asset) => asset.resolutionMeters === numeric || asset.requestedResolutionMeters === numeric);
}

export function metricCrs(extent) {
  const [west, south, east, north] = parseBbox(extent);
  const longitude = (west + east) / 2;
  const latitude = (south + north) / 2;
  if (latitude < -80 || latitude > 84) return latitude >= 0 ? 'EPSG:3413' : 'EPSG:3031';
  const zone = Math.max(1, Math.min(60, Math.floor((longitude + 180) / 6) + 1));
  return `EPSG:${(latitude >= 0 ? 32600 : 32700) + zone}`;
}

export function assetsGeojson(assets) {
  return featureCollection(assets.filter((asset) => asset.geometry || asset.bbox).map((asset) => {
    const shape = asset.geometry ? feature(asset.geometry) : bboxPolygon(asset.bbox);
    shape.properties = { id: asset.id, sourceId: asset.sourceId, product: asset.product, resolutionMeters: asset.resolutionMeters, downloaded: asset.downloaded };
    return shape;
  }));
}

import path from 'node:path';
import { mkdir, stat, writeFile, readdir } from 'node:fs/promises';
import { createWriteStream } from 'node:fs';
import { pipeline } from 'node:stream/promises';
import { createHash } from 'node:crypto';
import unzipper from 'unzipper';
import shp from 'shpjs';
import { bbox } from '@turf/turf';
import { load } from 'cheerio';
import { isContained, safeSegment } from './config.js';
import { HttpError, intersectsBoundary } from './spatial.js';

export function attributeLinks(attributes, fields = []) {
  const links = [];
  const entries = fields.length ? fields.map((key) => [key, attributes[key]]) : Object.entries(attributes || {});
  for (const [key, value] of entries) {
    if (typeof value !== 'string') continue;
    if (/^https?:\/\//i.test(value.trim())) links.push({ key, url: value.trim() });
    if (value.includes('<')) {
      const document = load(value);
      document('a[href]').each((index, element) => {
        const href = document(element).attr('href');
        if (/^https?:\/\//i.test(href)) links.push({ key, url: href });
      });
    }
  }
  return [...new Map(links.map((link) => [link.url, link])).values()];
}

export function extensionFor(url, mediaType = '') {
  const pathname = new URL(url).pathname;
  const matched = /\.(copc\.laz|laz|las|zlas|tiff?|zip|geojson|gpkg|img|jp2|png|jpe?g)(?:$)/i.exec(pathname);
  if (matched) return matched[1].toLowerCase();
  if (/tiff/i.test(mediaType)) return 'tif';
  if (/geo\+json|geojson/i.test(mediaType)) return 'geojson';
  if (/zip/i.test(mediaType)) return 'zip';
  return null;
}

export function canonicalDownloadUrl(input) {
  const url = new URL(input);
  if (url.hostname === 'download-telecharger.services.geo.ca' && url.pathname.startsWith('/pub/')) url.hostname = 'ftp.maps.canada.ca';
  return url.href;
}

export function attributeResolution(attributes) {
  const preferred = ['resolutionMeters', 'cellSizeMeters', 'Resolution', 'resolution', 'spacing', 'GSD', 'gsd', 'CellSize', 'RESOLUTION'];
  for (const key of preferred) {
    const value = attributes?.[key];
    if (value == null || value === '') continue;
    const match = /^\s*(\d+(?:\.\d+)?)\s*(?:m|metre|meter|metres|meters)?\s*$/i.exec(String(value));
    if (match && Number(match[1]) > 0) return Number(match[1]);
  }
  return null;
}

export async function extractArchive(filename, destination, maxBytes = 1024 ** 3 * 1024) {
  const archive = await unzipper.Open.file(filename);
  const total = archive.files.reduce((sum, entry) => sum + Number(entry.uncompressedSize || 0), 0);
  if (total > maxBytes || archive.files.length > 100000) throw new HttpError(413, 'Archive exceeds extraction limits. Adjust MAX_ARCHIVE_UNCOMPRESSED_GB or retain it as a raw archive.');
  await mkdir(destination, { recursive: true });
  const files = [];
  for (const entry of archive.files) {
    const relative = entry.path.replaceAll('\\', '/');
    if (/^[a-zA-Z]:|^\//.test(relative) || relative.split('/').includes('..')) throw new HttpError(400, 'Unsafe path in provider archive.');
    const target = path.resolve(destination, relative);
    if (!isContained(destination, target)) throw new HttpError(400, 'Unsafe archive path.');
    if (entry.type === 'Directory') { await mkdir(target, { recursive: true }); continue; }
    await mkdir(path.dirname(target), { recursive: true });
    const existing = await stat(target).catch((error) => { if (error.code === 'ENOENT') return null; throw error; });
    if (!existing) await pipeline(entry.stream(), createWriteStream(target, { flags: 'wx' }));
    else if (existing.size !== Number(entry.uncompressedSize)) throw new HttpError(409, 'Existing archive member has an unexpected size; raw data was not overwritten.');
    files.push(target);
  }
  return files;
}

export class VectorIndexes {
  constructor(config, network, gis) { this.config = config; this.network = network; this.gis = gis; }

  async query(sourceId, descriptor, query, options = {}) {
    const url = descriptor.indexUrl;
    this.network.validateUrl(url);
    let revision = '';
    const response = await this.network.response(url, { method: 'HEAD', signal: options.signal });
    if (response.ok) revision = response.headers.get('etag') || response.headers.get('last-modified') || '';
    await response.body?.cancel();
    const key = createHash('sha256').update(url + revision).digest('hex').slice(0, 20);
    const root = path.join(this.config.storageRoot, '.indexes', safeSegment(sourceId), key);
    const filename = path.join(root, path.basename(new URL(url).pathname));
    const extension = extensionFor(url) || 'zip';
    options.onProgress?.(`Caching ${sourceId} spatial index`);
    await this.network.download(url, filename, { signal: options.signal, extension: ['zip','geojson'].includes(extension) ? extension : undefined });
    let files = [filename];
    if (extension === 'zip') files = await extractArchive(filename, path.join(root, 'extracted'), 5 * 1024 ** 3);
    const vector = files.find((file) => descriptor.indexFile ? path.basename(file).toLowerCase() === descriptor.indexFile.toLowerCase()
      : /\.(shp|gpkg|geojson)$/i.test(file));
    if (!vector) throw new HttpError(502, 'Provider archive does not contain the configured vector index.');
    let features;
    if (/\.geojson$/i.test(vector)) {
      const { readFile } = await import('node:fs/promises');
      features = JSON.parse(await readFile(vector, 'utf8')).features;
    } else {
      try {
        const output = await this.gis.run('ogr2ogr', ['-f', 'GeoJSON', '/vsistdout/', vector, '-spat_srs', 'EPSG:4326', '-spat', ...query.bbox.map(String), '-t_srs', 'EPSG:4326'], { signal: options.signal });
        features = JSON.parse(output.stdout).features;
      } catch (error) {
        if (!/\.shp$/i.test(vector) || error.status !== 503) throw error;
        const parsed = await shp(vector.replace(/\.shp$/i, ''));
        features = (Array.isArray(parsed) ? parsed.flatMap((collection) => collection.features) : parsed.features);
      }
    }
    return (features || []).filter((item) => item.geometry && (options.fullGeometry || intersectsBoundary({ geometry: item.geometry }, query)));
  }
}

