      ...(request.query.returnGeometry==='true'?{geometry:{rings:(asset.geometry?.type==='Polygon'?asset.geometry:bboxPolygon(asset.bbox).geometry).coordinates,spatialReference:{wkid:4326}}}:{})})),exceededTransferLimit:false,localOnly:true});
