import assert from 'node:assert/strict';
import test from 'node:test';
import { assetsFromFeatures, builtInSources, ontarioExports, SourceRegistry } from '../src/sources.js';
import { normalizeBoundary } from '../src/spatial.js';
import { attributeLinks, canonicalDownloadUrl, geojsonFeatures } from '../src/indexes.js';
import { Catalog } from '../src/catalog.js';

const polygon = { type: 'Polygon', coordinates: [[[-79.5,43.5],[-79.4,43.5],[-79.4,43.6],[-79.5,43.6],[-79.5,43.5]]] };

test('catalog includes every plan source and source-native collection options', () => {
  const catalog = new Catalog(':memory:');
  try {
    const registry = new SourceRegistry({ defaultBufferMeters: 0 }, catalog, {}, {});
    for (const id of ['ontario','nrcan','pei','bc','quebec','alberta','nova-scotia','saskatchewan','usgs-3dep']) assert.ok(registry.get(id));
    assert.ok(registry.options(registry.get('usgs-3dep')).collections.some((collection) => collection.angularResolution === 1/9));
    assert.equal(registry.get('nrcan-pei').id, 'pei');
  } finally { catalog.close(); }
});

test('extracts actual BC spacing and link fields and Ontario HTML download links', () => {
  const source = builtInSources.find((source) => source.id === 'bc');
  const collection = source.collections.find((collection) => collection.id === 'bc-dtm-5');
  const assets = assetsFromFeatures([{ geometry: polygon, properties: { filename: 'native.tif', spacing: '1 metre', s3Url: 'https://nrs.objectstore.gov.bc.ca/example.tif' } }], source, collection);
  assert.equal(assets[0].resolutionMeters, 1);
  assert.equal(assets[0].product, 'dtm');
  assert.equal(attributeLinks({ Download: '<a href="https://example.gov/tile.laz">Download</a>' })[0].url, 'https://example.gov/tile.laz');
  assert.equal(canonicalDownloadUrl('https://download-telecharger.services.geo.ca/pub/example.tif'), 'https://ftp.maps.canada.ca/pub/example.tif');
});

test('Ontario exports split instead of silently coarsening a high-resolution request', () => {
  const source = builtInSources.find((source) => source.id === 'ontario');
  const query = normalizeBoundary({ bbox: [-79.5,43.5,-79.499,43.501] });
  const config = { maxExportPixels: 128, maxDiscoveryAssets: 1000 };
  const assets = ontarioExports(source, query, { resolution: 0.1 }, config);
  assert.ok(assets.length > 1);
  for (const asset of assets) {
    assert.ok(asset.width <= 128 && asset.height <= 128);
    assert.equal(asset.resolutionMeters, 0.5);
    assert.equal(asset.requestedResolutionMeters, 0.1);
    assert.equal(asset.resampled, true);
    assert.equal(new URL(asset.remoteUrl).searchParams.get('imageSR'), '32617');
  }
});

test('ArcGIS acquisition reads all IDs in batches instead of accepting a transfer cap', async () => {
  const catalog = new Catalog(':memory:');
  const counts = [];
  const network = { async json(input) {
    const url = new URL(input);
    if (url.searchParams.get('returnIdsOnly')) return { objectIds: Array.from({ length: 1201 }, (value,index) => index + 1) };
    const ids = url.searchParams.get('objectIds').split(','); counts.push(ids.length);
    return { features: ids.map((id) => ({ type: 'Feature', id, geometry: polygon, properties: {} })) };
  } };
  try {
    const registry = new SourceRegistry({ maxDiscoveryAssets: 2000 }, catalog, network, {});
    assert.equal((await registry.arcgisFeatures('https://example.gov/FeatureServer/0', normalizeBoundary({ bbox: [-80,43,-79,44] }))).length, 1201);
    assert.deepEqual(counts, [500,500,201]);
  } finally { catalog.close(); }
});

test('ImageServer footprints use its supported JSON response format', async () => {
  const catalog = new Catalog(':memory:');
  const network = { async json(input) {
    const url = new URL(input);
    if (url.searchParams.get('returnIdsOnly')) return { objectIds: [1] };
    assert.equal(url.searchParams.get('f'), 'json');
    return { features: [{ attributes: { OBJECTID: 1 }, geometry: { rings: polygon.coordinates, spatialReference: { wkid: 4326 } } }] };
  } };
  try {
    const registry = new SourceRegistry({ maxDiscoveryAssets: 2000 }, catalog, network, {});
    const features = await registry.arcgisFeatures('https://example.gov/ImageServer', normalizeBoundary({ bbox: [-80,43,-79,44] }));
    assert.equal(features[0].geometry.type, 'Polygon');
  } finally { catalog.close(); }
});

test('NRCan coverage indexes accept single GeoJSON Features as well as collections', () => {
  const footprint = { type: 'Feature', properties: {}, geometry: polygon };
  assert.deepEqual(geojsonFeatures(footprint), [footprint]);
  assert.deepEqual(geojsonFeatures({ type: 'FeatureCollection', features: [footprint] }), [footprint]);
  assert.equal(geojsonFeatures(polygon)[0].geometry.type, 'Polygon');
});

test('PEI DSM and all-resolution requests are not suppressed by preferred DTM tile delivery',async()=>{
  const catalog=new Catalog(':memory:');
  const network={validateUrl(){}};const registry=new SourceRegistry({defaultBufferMeters:0,maxDiscoveryAssets:1000},catalog,network,{});
  const calls=[];
  registry.stacAssets=async(source,collection,query)=>{calls.push(collection.id);return[{sourceId:source.id,collectionId:collection.id,remoteUrl:`https://example.gov/${collection.id}.tif`,extension:'tif',product:'dsm',bbox:query.bbox,resolutionMeters:1}];};
  try{const plan=await registry.discover({sourceIds:['pei'],products:['dsm'],bbox:[-63.01,46.41,-62.99,46.43]});assert.ok(plan.complete&&plan.assetCount>0);assert.ok(calls.includes('hrdem-lidar'));}finally{catalog.close();}
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp,writeFile,rm } from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import request from 'supertest';
import { writeArrayBuffer } from 'geotiff';
import { createService } from '../src/app.js';

test('local API serves discovery, Range files, Scorecarder manifests, STAC, and bounded raster queries',async()=>{
  const root=await mkdtemp(path.join(os.tmpdir(),'terrain-api-'));const service=await createService({storageRoot:root,catalogPath:':memory:',updateCheckDays:0,startJobs:false});
  try{
    await request(service.app).get('/api/health').expect(200);
    const sources=await request(service.app).get('/api/sources').expect(200);assert.ok(sources.body.sources.length>=9);
    await request(service.app).post('/api/courses').send({id:'fixture',name:'Fixture',country:'CA',province:'ON',bbox:[-79.5,43.59,-79.49,43.6],bufferMeters:0}).expect(201);
    const values=Array.from({length:100},(value,index)=>100+index);
    const bytes=Buffer.from(writeArrayBuffer(values,{width:10,height:10,BitsPerSample:[8],SampleFormat:[1],ModelPixelScale:[0.001,0.001,0],ModelTiepoint:[0,0,0,-79.5,43.6,0],GeographicTypeGeoKey:4326,GTModelTypeGeoKey:2,GTRasterTypeGeoKey:1,GDAL_NODATA:'255'}));
    const filename=path.join(root,'fixture.tif');await writeFile(filename,bytes);
    const asset=service.catalog.saveAsset({sourceId:'ontario',product:'dtm',extension:'tif',path:filename,bbox:[-79.5,43.59,-79.49,43.6],resolutionMeters:1,bytes:bytes.length,sha256:'fixture-hash'});service.catalog.linkAsset('fixture',asset.id);
    const binary=await request(service.app).get(`/api/assets/${asset.id}/download.tif`).set('Range','bytes=0-7').expect(206);assert.equal(binary.headers['content-range'],`bytes 0-7/${bytes.length}`);
    const manifest=await request(service.app).get('/api/scorecarder/manifest?bbox=-79.5,43.59,-79.49,43.6').expect(200);assert.equal(manifest.body.assets.length,1);assert.ok(manifest.body.assets[0].url.endsWith('.tif'));assert.equal(manifest.body.assets[0].bbox.minLng,-79.5);
    const arcgis=await request(service.app).get('/api/scorecarder/query').query({geometry:JSON.stringify({xmin:-79.5,ymin:43.59,xmax:-79.49,ymax:43.6})}).expect(200);assert.equal(arcgis.body.features.length,1);assert.ok(arcgis.body.features[0].attributes.downloadUrl.endsWith('.tif'));
    const stac=await request(service.app).post('/api/stac/search').send({bbox:[-79.5,43.59,-79.49,43.6],collections:['ontario']}).expect(200);assert.equal(stac.body.features.length,1);
    await request(service.app).get('/api/stac/collections/ontario/items').expect(200).then(result=>assert.equal(result.body.features.length,1));
    await request(service.app).get('/api/stac/collections/derived').expect(200);
    const terrain=await request(service.app).get('/api/course/fixture/terrain').expect(200);assert.ok(terrain.body.dem.endsWith('.tif'));
    const sample=await request(service.app).get('/api/terrain/elevation?longitude=-79.4995&latitude=43.5995').expect(200);assert.equal(sample.body.points[0].elevation,100);
    const grid=await request(service.app).get(`/api/terrain/grid?assetId=${asset.id}&width=16&height=16`).expect(200);assert.equal(grid.body.values.length,256);assert.equal(grid.body.localOnly,true);
    const preview=await request(service.app).get(`/api/assets/${asset.id}/preview.png`).expect(200);assert.ok(preview.headers['content-type'].includes('image/png'));
    await request(service.app).get('/api/terrain/query?bbox=-75,43,-74,44').expect(200).then(result=>assert.equal(result.body.total,0));
    await request(service.app).get('/api/terrain/query?limit=100000').expect(400);
    await request(service.app).get('/api/openapi.json').expect(200);await request(service.app).get('/docs').expect(200);
  }finally{await service.close();await rm(root,{recursive:true,force:true});}
});

test('API authentication, CORS origin checks, and DNS-rebinding Host protection',async()=>{
  const root=await mkdtemp(path.join(os.tmpdir(),'terrain-auth-'));const service=await createService({storageRoot:root,catalogPath:':memory:',apiKey:'test-key',updateCheckDays:0,startJobs:false});
  try{
    await request(service.app).get('/api/settings').expect(401);
    await request(service.app).get('/api/settings').set('Authorization','Bearer test-key').expect(200);
    await request(service.app).post('/api/courses').set('Authorization','Bearer test-key').set('Origin','https://untrusted.example').send({}).expect(403);
    await request(service.app).get('/api/health').set('Host','attacker.example').expect(403);
    await request(service.app).get('/api/health').expect(200);
  }finally{await service.close();await rm(root,{recursive:true,force:true});}
});

