var
  Locations: TInputDirWizardPage;
  Connection: TInputQueryWizardPage;
  Security: TInputOptionWizardPage;
  ConfigurationFailed: Boolean;

function GetStateDirectory(Param: String): String;
begin
  Result := Locations.Values[0];
end;

function Quote(Value: String): String;
begin
  Result := '"' + Value + '"';
end;

procedure InitializeWizard;
var
  State: String;
begin
  if IsAdminInstallMode then begin
    State := ExpandConstant('{commonappdata}\TerrainServer');
    RegQueryStringValue(HKLM64, '{#RegistryKey}', 'StateDirectory', State);
  end else begin
    State := ExpandConstant('{localappdata}\TerrainServer');
    RegQueryStringValue(HKCU, '{#RegistryKey}', 'StateDirectory', State);
  end;
  Locations := CreateInputDirPage(wpSelectDir, 'Configuration and Terrain Storage', 'Choose persistent directories outside the program folder.', 'Existing configuration, catalog, and terrain files are preserved during upgrades and uninstall.', False, '');
  Locations.Add('Configuration, catalog, and logs:');
  Locations.Add('Default terrain storage:');
  Locations.Values[0] := ExpandConstant('{param:STATEDIR|' + State + '}');
  Locations.Values[1] := ExpandConstant('{param:STORAGEROOT|' + Locations.Values[0] + '\terrain-data}');
  Connection := CreateInputQueryPage(Locations.ID, 'Server Connection', 'Choose the listening port and network binding.', 'Loopback is recommended behind a TLS reverse proxy. Remote bindings always require a generated API key. Existing .env settings take precedence on upgrades.');
  Connection.Add('TCP port:', False);
  Connection.Add('Bind address (127.0.0.1 or 0.0.0.0):', False);
  Connection.Values[0] := ExpandConstant('{param:PORT|3123}');
  Connection.Values[1] := ExpandConstant('{param:BIND|127.0.0.1}');
  Security := CreateInputOptionPage(Connection.ID, 'API Authentication', 'Keep the API key in the protected configuration file.', 'A generated key is stored only in .env, not in service arguments or installer logs. Read that file locally to connect authenticated clients.', False, False);
  Security.Add('Require an API key even when listening only on loopback');
  Security.Values[0] := ExpandConstant('{param:REQUIREKEY|0}') = '1';
end;

function NextButtonClick(CurPageID: Integer): Boolean;
var
  Port: Integer;
begin
  Result := True;
  if CurPageID = Locations.ID then begin
    if (Length(Locations.Values[0]) < 4) or (Length(Locations.Values[1]) < 4) or (ExtractFileDrive(Locations.Values[0]) = '') or (ExtractFileDrive(Locations.Values[1]) = '') then begin
      MsgBox('Choose absolute, dedicated directories, not volume roots.', mbError, MB_OK); Result := False;
    end;
  end;
  if CurPageID = Connection.ID then begin
    Port := StrToIntDef(Connection.Values[0], 0);
    if (Port < 1) or (Port > 65535) then begin MsgBox('Port must be from 1 to 65535.', mbError, MB_OK); Result := False; end;
    if (Connection.Values[1] <> '127.0.0.1') and (Connection.Values[1] <> 'localhost') and (Connection.Values[1] <> '0.0.0.0') and (Connection.Values[1] <> '::1') and (Connection.Values[1] <> '::') then begin MsgBox('Choose 127.0.0.1, localhost, ::1, 0.0.0.0, or ::.', mbError, MB_OK); Result := False; end;
  end;
end;

function PrepareToInstall(var NeedsRestart: Boolean): String;
var
  ExitCode: Integer;
begin
  Result := '';
  if IsAdminInstallMode and WizardIsTaskSelected('service') then begin
    ExtractTemporaryFile('service.ps1');
    if not ExecAndLogOutput(ExpandConstant('{sys}\WindowsPowerShell\v1.0\powershell.exe'), '-NoProfile -ExecutionPolicy Bypass -File ' + Quote(ExpandConstant('{tmp}\service.ps1')) + ' -Mode Prepare -AppDirectory ' + Quote(WizardDirValue), '', SW_SHOWNORMAL, ewWaitUntilTerminated, ExitCode, nil) then ExitCode := -1;
    if ExitCode <> 0 then Result := 'Could not prepare the Windows service. An existing TerrainServer service must belong to this installation. Check administrator rights and the selected program folder.';
  end;
end;

procedure CurStepChanged(CurStep: TSetupStep);
var
  Arguments: String;
  ExitCode: Integer;
begin
  if CurStep = ssPostInstall then begin
    Arguments := '-NoProfile -ExecutionPolicy Bypass -File ' + Quote(ExpandConstant('{app}\installer\windows\service.ps1')) + ' -Mode Configure -AppDirectory ' + Quote(ExpandConstant('{app}')) + ' -StateDirectory ' + Quote(Locations.Values[0]) + ' -StorageRoot ' + Quote(Locations.Values[1]) + ' -Port ' + Connection.Values[0] + ' -BindAddress ' + Quote(Connection.Values[1]);
    if Security.Values[0] then Arguments := Arguments + ' -RequireApiKey';
    if IsAdminInstallMode and WizardIsTaskSelected('service') then Arguments := Arguments + ' -InstallService';
    if not ExecAndLogOutput(ExpandConstant('{sys}\WindowsPowerShell\v1.0\powershell.exe'), Arguments, '', SW_SHOWNORMAL, ewWaitUntilTerminated, ExitCode, nil) then ExitCode := -1;
    Log('Service configuration exit code: ' + IntToStr(ExitCode));
    if ExitCode <> 0 then begin
      ConfigurationFailed := True;
      RaiseException('Configuration or service startup failed. Check the setup log, configuration paths, port availability, and state-directory logs. Existing terrain data has not been removed.');
    end;
  end;
end;

function GetCustomSetupExitCode: Integer;
begin
  if ConfigurationFailed then Result := 17 else Result := 0;
end;

param(
    [ValidateSet('Prepare','Configure','Remove')][string]$Mode = 'Configure',
    [Parameter(Mandatory=$true)][string]$AppDirectory,
    [string]$StateDirectory,
    [string]$StorageRoot,
    [int]$Port = 3123,
    [string]$BindAddress = '127.0.0.1',
    [switch]$RequireApiKey,
    [switch]$InstallService
)
$ErrorActionPreference = 'Stop'
$env:PSModulePath = [IO.Path]::Combine($PSHOME, 'Modules')
$AppDirectory = [IO.Path]::GetFullPath($AppDirectory).TrimEnd('\')
$Wrapper = Join-Path $AppDirectory 'TerrainServerService.exe'
$Principal = [Security.Principal.WindowsPrincipal]::new([Security.Principal.WindowsIdentity]::GetCurrent())
$Elevated = $Principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

function Get-OwnedService {
    $Service = Get-CimInstance Win32_Service -Filter "Name='TerrainServer'" -ErrorAction Stop
    if ($Service) {
        $Match = [regex]::Match($Service.PathName, '^(?:"([^"]+)"|(\S+))')
        $Binary = if ($Match.Groups[1].Success) { $Match.Groups[1].Value } else { $Match.Groups[2].Value }
        if (-not [string]::Equals([IO.Path]::GetFullPath($Binary), $Wrapper, [StringComparison]::OrdinalIgnoreCase)) {
            throw 'A TerrainServer service belongs to another installation. Upgrade that installation in place or remove its service explicitly.'
        }
    }
    return $Service
}

function Stop-OwnedService {
    $Service = Get-OwnedService
    if ($Service -and $Service.State -ne 'Stopped') {
        Stop-Service -Name TerrainServer -ErrorAction Stop
        (Get-Service TerrainServer).WaitForStatus('Stopped', [TimeSpan]::FromSeconds(60))
    }
    return $Service
}

function Protect-State([string]$Directory) {
    $Directory = [IO.Path]::GetFullPath($Directory).TrimEnd('\')
    if ($Directory -eq [IO.Path]::GetPathRoot($Directory).TrimEnd('\') -or $Directory -eq $AppDirectory -or $Directory.StartsWith($AppDirectory+'\', [StringComparison]::OrdinalIgnoreCase)) {
        throw 'Choose a dedicated state directory outside the program directory, not a volume root.'
    }
    [IO.Directory]::CreateDirectory($Directory) | Out-Null
    $Acl = Get-Acl -LiteralPath $Directory
    $Acl.SetAccessRuleProtection($true, $false)
    foreach ($Sid in @('S-1-5-18','S-1-5-32-544')) {
        $Rule = [Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new($Sid),'FullControl','ContainerInherit,ObjectInherit','None','Allow')
        $Acl.AddAccessRule($Rule)
    }
    $User = [Security.Principal.WindowsIdentity]::GetCurrent().User
    $Acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($User,'FullControl','ContainerInherit,ObjectInherit','None','Allow'))
    if ($InstallService) {
        $Acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new('S-1-5-19'),'Modify','ContainerInherit,ObjectInherit','None','Allow'))
    }
    Set-Acl -LiteralPath $Directory -AclObject $Acl
}

function Grant-ServiceStorage([string]$Directory) {
    $Acl = Get-Acl -LiteralPath $Directory
    $Acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new('S-1-5-19'),'Modify','ContainerInherit,ObjectInherit','None','Allow'))
    Set-Acl -LiteralPath $Directory -AclObject $Acl
}

try {
    if ($Mode -eq 'Prepare') {
        if (-not $Elevated) { throw 'Service installation requires an administrator.' }
        Stop-OwnedService | Out-Null
        exit 0
    }
    if ($Mode -eq 'Remove') {
        if (-not $Elevated) { throw 'Service removal requires an administrator.' }
        $Service = Stop-OwnedService
        if ($Service) { & $Wrapper uninstall; if ($LASTEXITCODE -ne 0) { throw 'Windows service removal failed.' } }
        exit 0
    }
    if ($InstallService -and -not $Elevated) { throw 'Run Setup as administrator to register the Windows service.' }
    if (-not $StateDirectory) { throw 'StateDirectory is required.' }
    Protect-State $StateDirectory
    $Arguments = @((Join-Path $AppDirectory 'scripts\configure-service.js'),'--app-dir',$AppDirectory,'--state-dir',$StateDirectory,'--port',"$Port",'--host',$BindAddress,'--platform','win32')
    if ($StorageRoot) { $Arguments += @('--storage-root',$StorageRoot) }
    if ($RequireApiKey) { $Arguments += '--require-key' }
    & (Join-Path $AppDirectory 'runtime\node\node.exe') @Arguments
    if ($LASTEXITCODE -ne 0) { throw 'Service configuration failed. Check the selected paths and settings.' }
    $Configuration = Get-Content -LiteralPath (Join-Path $AppDirectory 'installation.json') -Raw | ConvertFrom-Json
    if ($InstallService) {
        foreach ($Directory in @($Configuration.storageRoot, (Split-Path $Configuration.catalogPath -Parent))) { Grant-ServiceStorage $Directory }
        $Address = if ($Configuration.host -eq 'localhost') { [Net.IPAddress]::Loopback } else { [Net.IPAddress]::Parse($Configuration.host) }
        $Listener = [Net.Sockets.TcpListener]::new($Address, $Configuration.port)
        try { $Listener.Start() } finally { $Listener.Stop() }
        $Service = Get-OwnedService
        if (-not $Service) { & $Wrapper install; if ($LASTEXITCODE -ne 0) { throw 'Windows service registration failed.' } }
        & $Wrapper start
        if ($LASTEXITCODE -ne 0) { throw 'Windows service startup failed. Inspect the logs in the state directory.' }
    }
    Write-Output 'Installation configured. Configuration, catalog, and terrain files are preserved by uninstall.'
    exit 0
} catch {
    Write-Error $_.Exception.Message -ErrorAction Continue
    exit 1
}

