}
async function stop(child){if(!child||child.exitCode!==null)return;const exited=once(child,'exit');child.kill('SIGTERM');await exited;}
async function json(base,pathname,key){const response=await fetch(base+pathname,{headers:key?{Authorization:`Bearer ${key}`}:{},signal:AbortSignal.timeout(30000)});assert.equal(response.status,200,`${pathname}: ${await response.clone().text()}`);return response.json();}

async function main(){
  if(process.platform!=='win32')throw new Error('The Windows setup integration test requires Windows.');
  const {values:argumentsValues}=parseArgs({options:{'gis-env':{type:'string'}}});
  const localConfig=dotenv.parse(await readFile(path.join(root,'.env'),'utf8').catch(()=>''));
  const gisEnv=argumentsValues['gis-env']||process.env.GIS_ENV_ROOT||localConfig.GIS_ENV_ROOT;
  if(!gisEnv)throw new Error('Supply --gis-env or configure GIS_ENV_ROOT for a fresh installer build.');
  console.log('Building a fresh Windows payload before installer integration validation.');
  await run(process.execPath,[path.join(root,'scripts/build-installer.js'),'--gis-env',gisEnv]);
  const stage=path.join(root,'build/staging/windows-x64');await access(path.join(stage,'runtime/node/node.exe'));
  const {version}=JSON.parse(await readFile(path.join(root,'package.json'),'utf8'));
  const testRoot=await mkdtemp(path.join(root,'build/installer-check-'));
  const appDir=path.join(testRoot,'test program'),stateDir=path.join(testRoot,'state'),storageRoot=path.join(testRoot,'terrain files');
  const compiler=process.env.ISCC_PATH||path.join(process.env.LOCALAPPDATA,'Programs/Inno Setup 6/ISCC.exe');
  await run(compiler,['/Qp','/DVerificationBuild',`/DStageDir=${stage}`,`/DOutputDir=${testRoot}`,`/DAppVersion=${version}`,path.join(root,'installer/windows/setup.iss')]);
  const setup=path.join(testRoot,`TerrainServer-InstallerVerification-${version}-windows-x64-setup.exe`);
  const port=await freePort();const args=['/CURRENTUSER','/VERYSILENT','/SUPPRESSMSGBOXES','/NORESTART',`/DIR=${appDir}`,`/STATEDIR=${stateDir}`,`/STORAGEROOT=${storageRoot}`,`/PORT=${port}`,'/BIND=127.0.0.1',`/LOG=${path.join(testRoot,'install.log')}`];
