  const linux=gis.environment('linux');assert.equal(linux.GDAL_DATA,path.join(root,'share/gdal'));assert.equal(linux.PROJ_DATA,path.join(root,'share/proj'));assert.ok(linux.LD_LIBRARY_PATH.startsWith(path.join(root,'lib')));assert.equal(linux.PROJ_NETWORK,'OFF');assert.ok(linux.PATH.startsWith(path.join(root,'bin')));
