  $('#job-detail').innerHTML=`<dl class="detail-list"><dt>Status</dt><dd><span class="badge ${escapeHtml(job.status)}">${escapeHtml(job.status)}</span></dd><dt>Progress</dt><dd>${progressBar(job)}</dd><dt>Transferred</dt><dd>${bytes(job.progress.bytes||0)}</dd><dt>Destination</dt><dd>${escapeHtml(job.payload.storageRoot)}</dd></dl>${job.error?`<p class="job-error">${escapeHtml(job.error)}</p>`:''}`;
