  app.get('/api/stac',(request,response)=>response.json({type:'Catalog',id:'terrainserver',stac_version:'1.0.0',description:'Locally acquired government terrain',links:[{rel:'self',href:`${base(request)}/api/stac`},{rel:'data',href:`${base(request)}/api/stac/collections`},{rel:'search',href:`${base(request)}/api/stac/search`,method:'POST'}],conformsTo:['https://api.stacspec.org/v1.0.0/core','https://api.stacspec.org/v1.0.0/item-search']}));
