  storageRoot:z.string().refine(value=>path.isAbsolute(value)&&!/[\r\n\0]/.test(value),'Use an absolute storage path').optional(),assetIds:z.array(z.string()).max(100000).optional(),
  courseId:z.string().optional(),planId:z.string().optional(),allowPartial:z.boolean().optional(),processAfterDownload:z.boolean().optional(),resolutionMeters:z.number().positive().optional(),
  contourIntervals:z.array(z.number().positive()).min(1).max(20).optional(),resampling:z.enum(['near','bilinear','cubic','cubicspline','lanczos','average','mode']).optional(),
  groundOnly:z.boolean().optional(),preferPointCloud:z.boolean().optional(),zScale:z.number().positive().optional(),hillshadeStyle:z.enum(['classic','multidirectional']).optional(),slopeUnits:z.enum(['degrees','percent']).optional()}).passthrough();

export async function createService(overrides={}) {
  const config=loadConfig(overrides);await mkdir(config.storageRoot,{recursive:true});
