  const saveCourse=async(request,response)=>{const previous=request.params.id?courseFor(request.params.id):null;const course=catalog.saveCourse({...previous,...request.body,...(request.params.id?{id:request.params.id}:{})});const root=courseDirectory(config.storageRoot,course);await mkdir(root,{recursive:true});await writeFile(path.join(root,'metadata.json'),JSON.stringify(course,null,2));await writeFile(path.join(root,'course_boundary.geojson'),JSON.stringify(course.boundary));response.status(previous?200:201).json(course);};
