    const bytes=Buffer.from(writeArrayBuffer(Array.from({length:100},()=>100),{width:10,height:10,BitsPerSample:[8],SampleFormat:[1],ModelPixelScale:[0.001,0.001,0],ModelTiepoint:[0,0,0,-79.5,43.6,0],GeographicTypeGeoKey:4326,GTModelTypeGeoKey:2,GTRasterTypeGeoKey:1}));
    const filename=path.join(storageRoot,'fixture.tif');await writeFile(filename,bytes);
    const seed=`import {Catalog} from ${JSON.stringify(pathToFileURL(path.join(appDir,'src/catalog.js')).href)};const catalog=new Catalog(${JSON.stringify(installation.catalogPath)});const asset=catalog.saveAsset({sourceId:'ontario',title:'Installer fixture',product:'dtm',extension:'tif',path:${JSON.stringify(filename)},bbox:[-79.5,43.59,-79.49,43.6],resolutionMeters:1,bytes:${bytes.length},sha256:'fixture-hash'});catalog.saveAsset({...asset,id:undefined,sourceId:'derived',product:'hillshade',url:'https://example.gov/visualization.tif',title:'Visualization fixture'});console.log(asset.id);catalog.close();`;
    const seeded=await run(node,['--input-type=module','-e',seed],{cwd:appDir});const assetId=seeded.match(/^[a-f0-9]{32}$/m)?.[0];assert.ok(assetId,seeded);
