        const metadata = await rasterMetadata(filename);
        const info = JSON.parse((await this.gis.run('gdalinfo', ['-json',filename], { signal: context.signal })).stdout);
        asset = this.catalog.saveAsset({ ...asset, id: createHash('sha256').update(`${id}:scorecarder-geotiff-v1`).digest('hex').slice(0,32),
          parentAssetId: id, remoteUrl: null, url: null, path: filename, extension: 'tif', title: `${asset.title || id} GeoTIFF`,
          bbox: info.wgs84Extent ? geometryBbox(feature(info.wgs84Extent)) : asset.bbox, geometry: null,
          bytes: (await stat(filename)).size, sha256: await fileHash(filename), ...metadata });
