    if (!assets.length || assets.some((asset) => !asset?.downloaded)) throw new HttpError(409, 'No complete local terrain inputs are available. Download assets first.');
    if (!course && !payload.bbox && !payload.boundary) throw new HttpError(400, 'Processing requires a course or a boundary.');
    const query = normalizeBoundary({ ...(course || {}), ...payload, bufferMeters: payload.bufferMeters ?? course?.bufferMeters ?? 0 });
    if (assets.some((asset) => asset.extension === 'zip')) {
      const expanded = await this.expandArchives(assets.map((asset) => asset.id), context);
