      const terrainFile = path.join(working, 'dtm.tif');
      if (clouds.length && (payload.preferPointCloud !== false || !terrainRasters.length)) {
        const raster = path.join(working, 'point-ground.tif');
        const pipelineFile = path.join(working, 'dtm-pipeline.json');
        await writeFile(pipelineFile, JSON.stringify(pointCloudPipeline(clouds.map((asset) => asset.path), query.bbox, raster, { ...payload, resolutionMeters: resolution }), null, 2));
        await command('pdal', ['pipeline',pipelineFile]); await warp([raster], terrainFile);
      } else {
        const ordered = terrainRasters.sort((left,right) => (right.effectiveCellSizeMeters || right.resolutionMeters || 1000) - (left.effectiveCellSizeMeters || left.resolutionMeters || 1000)
          || String(left.providerMetadata?.datetime || '').localeCompare(String(right.providerMetadata?.datetime || '')));
