          const pipelineFile = path.join(working, 'dsm-pipeline.json');
          await writeFile(pipelineFile, JSON.stringify(pointCloudPipeline(clouds.map((asset) => asset.path), query.bbox, raster, { ...payload, surface: 'dsm', resolutionMeters: resolution }), null, 2));
