    const cached={downloaded:true,path:destination,bytes:first.bytes,sha256:first.sha256,etag:first.etag,localFile:{mtimeMs:first.mtimeMs}};
    const reused=await network.download(url,destination,{extension:'tif',cachedAsset:cached,sha256:checksum});assert.equal(reused.reused,true);assert.equal(reused.etag,'"complete"');assert.equal(requests,1);
    const full=path.join(root,'fully-received.tif');await writeFile(`${full}.part`,content);await writeFile(`${full}.part.json`,JSON.stringify({url,etag:'"complete"',total:content.length}));
    const recovered=await network.download(url,full,{extension:'tif',sha256:checksum});assert.equal(recovered.recovered,true);assert.equal(recovered.reused,true);assert.equal(requests,1);assert.deepEqual(await readFile(full),content);
    const partial=path.join(root,'interrupted.tif');await writeFile(`${partial}.part`,content.subarray(0,4096));await writeFile(`${partial}.part.json`,JSON.stringify({url,etag:'"complete"',total:content.length}));
    const resumed=await network.download(url,partial,{extension:'tif',sha256:checksum});assert.equal(resumed.resumedBytes,4096);assert.equal(resumedOffset,4096);assert.equal(requests,2);assert.deepEqual(await readFile(partial),content);
    const changed=Buffer.from(content);changed[20]=99;await writeFile(destination,changed);const future=new Date((await stat(destination)).mtimeMs+60000);await utimes(destination,future,future);
    await assert.rejects(network.download(url,destination,{extension:'tif',cachedAsset:cached}),/recorded checksum/);assert.equal(requests,2);assert.deepEqual(await readFile(destination),changed);
  }finally{await network.close();await new Promise(resolve=>server.close(resolve));await rm(root,{recursive:true,force:true});}
