    service.catalog.saveAsset({...service.catalog.asset(rawZip.id),scorecarderPreparation:null});service.catalog.saveAsset({...service.catalog.asset(tile.id),localFile:null});
    const adopting=once(service.jobs,'settled');const adopted=await request(service.app).post('/api/sources/preset-fixture/acquire').send({storageRoot:repository}).expect(202);await adopting;
    assert.equal(service.catalog.job(adopted.body.id).status,'completed');assert.equal(downloads,2);assert.equal(inspections,initialInspections);
    await rm(tile.path);const repairing=once(service.jobs,'settled');const repaired=await request(service.app).post('/api/sources/preset-fixture/acquire').send({storageRoot:repository}).expect(202);await repairing;
    assert.equal(service.catalog.job(repaired.body.id).status,'completed');assert.equal(downloads,2);assert.equal(inspections,initialInspections+1);assert.deepEqual(await readFile(tile.path),bytes);
