    assert.equal(downloads,1);assert.equal(catalog.job(copied.id).progress.result.reused,1);assert.equal(catalog.job(copied.id).progress.result.bytes,0);
    await rm(catalog.asset(asset.id).path);const alternate=once(manager,'settled');const recoveredCopy=manager.enqueue('download',{assetIds:[asset.id],courseId:course.id,storageRoot:secondRoot});await alternate;
    assert.equal(catalog.job(recoveredCopy.id).status,'completed');assert.equal(downloads,1);assert.deepEqual(await readFile(catalog.asset(asset.id).path),content);
