const buildRoot=path.resolve(values['build-dir']||path.join(root,'build')),cache=path.join(buildRoot,'cache'),output=path.join(root,'dist');

function run(executable,args,options={}){
  return new Promise((resolve,reject)=>{
    const child=spawn(executable,args,{cwd:root,windowsHide:true,stdio:options.capture?'pipe':'inherit',...options});let stdout='',stderr='';
    child.stdout?.on('data',chunk=>{stdout+=chunk;});child.stderr?.on('data',chunk=>{stderr+=chunk;});
    child.once('error',reject);child.once('exit',code=>{if(code!==0&&!options.allowFailure)reject(new Error(`${path.basename(executable)} exited ${code}: ${stderr||stdout}`));else resolve({code,stdout,stderr});});
  });
}
async function hash(filename){const digest=createHash('sha256');for await(const chunk of createReadStream(filename))digest.update(chunk);return digest.digest('hex');}
async function download(url,filename,expected){
  await mkdir(path.dirname(filename),{recursive:true});
  if(await access(filename).then(()=>true,()=>false)){if(!expected||await hash(filename)===expected)return filename;await rm(filename);}
  console.log(`Downloading ${path.basename(filename)}`);
  const response=await fetch(url,{signal:AbortSignal.timeout(180000),headers:{'User-Agent':'TerrainServer-Installer-Builder'}});
  if(!response.ok)throw new Error(`Download ${response.status}: ${url}`);
  await pipeline(Readable.fromWeb(response.body),createWriteStream(filename+'.part'));await rename(filename+'.part',filename);
  if(expected&&await hash(filename)!==expected){await rm(filename);throw new Error(`SHA256 mismatch for ${filename}`);}
  return filename;
}
async function nodeRuntime(stage){
  const releases=await fetch('https://nodejs.org/dist/index.json',{signal:AbortSignal.timeout(60000)}).then(response=>{if(!response.ok)throw new Error('Cannot read official Node.js releases.');return response.json();});
  const version=values['node-version']||releases.find(item=>item.lts&&item.version.startsWith('v24.'))?.version;
  if(!/^v24\.\d+\.\d+$/.test(version||''))throw new Error('Use a published Node.js 24 LTS version (v24.x.y).');
  const distribution=`node-${version}-${windows?'win-x64':'linux-x64'}`;
  const basename=distribution+(windows?'.zip':'.tar.xz');
  const checksums=await fetch(`https://nodejs.org/dist/${version}/SHASUMS256.txt`,{signal:AbortSignal.timeout(60000)}).then(response=>{if(!response.ok)throw new Error('Cannot read official Node.js checksums.');return response.text();});
  const expected=checksums.split('\n').map(line=>line.trim().split(/\s+/)).find(parts=>parts[1]===basename)?.[0];
  if(!expected)throw new Error('Official Node.js release checksum not found.');
  const archive=await download(`https://nodejs.org/dist/${version}/${basename}`,path.join(cache,basename),expected);
  const extracted=path.join(buildRoot,'node-extracted');await rm(extracted,{recursive:true,force:true});await mkdir(extracted,{recursive:true});
  if(windows)await (await unzipper.Open.file(archive)).extract({path:extracted});else await run('tar',['-xf',archive,'-C',extracted],{capture:true});
  const nodeDir=path.join(stage,'runtime','node');await mkdir(nodeDir,{recursive:true});
  if(!windows)await mkdir(path.join(nodeDir,'bin'));
  for(const filename of [windows?'node.exe':'bin/node','LICENSE','README.md'])await copyFile(path.join(extracted,distribution,filename),path.join(nodeDir,filename));
  await rm(extracted,{recursive:true,force:true});return {version,archive:basename,sha256:expected};
}
async function sevenZipPackage(){
  const release=windows?{subdir:'win-64',build:'h477610d_0',sha256:'0a76e461ae367abc94af8e58cc78db584a5bdfbb8c5f7049becc7ac293a90fdb'}:{subdir:'linux-64',build:'h4dbf13b_0',sha256:'7f24bd0c453cd6f524d0089cadfa2c6aaf7b2ab010fa936b87225abef9bee886'};
  const basename=`7zip-26.05-${release.build}.conda`,url=`https://conda.anaconda.org/conda-forge/${release.subdir}/${basename}`;
  const archive=await download(url,path.join(cache,basename),release.sha256);
  const directory=path.join(buildRoot,'sevenzip',targetLabel);await rm(directory,{recursive:true,force:true});await mkdir(directory,{recursive:true});
  await (await unzipper.Open.file(archive)).extract({path:directory});
  for(const filename of await readdir(directory))if(/^(pkg|info)-.*\.tar\.zst$/.test(filename)){
    const payload=path.join(directory,filename+'.tar');await writeFile(payload,zstdDecompressSync(await readFile(path.join(directory,filename))));await run('tar',['-xf',payload,'-C',directory],{capture:true});await rm(payload);
  }
  const record=JSON.parse(await readFile(path.join(directory,'info/index.json'),'utf8'));
  const paths=JSON.parse(await readFile(path.join(directory,'info/paths.json'),'utf8'));
  return {directory,record:{...record,url,sha256:release.sha256,files:paths.paths.map(item=>item._path)}};
}

async function gisRuntime(stage,source){
  if(!source)throw new Error('Supply --gis-env pointing to a working native conda-forge GDAL/PDAL environment.');
  const records=new Map();for(const filename of await readdir(path.join(source,'conda-meta'))){if(!filename.endsWith('.json'))continue;const record=JSON.parse(await readFile(path.join(source,'conda-meta',filename),'utf8'));records.set(record.name,record);}
  const decoder=await sevenZipPackage();records.set(decoder.record.name,decoder.record);
  const selected=new Set();
  function visit(name){if(name.startsWith('__')||selected.has(name))return;const record=records.get(name);if(!record)throw new Error(`Missing GIS runtime dependency: ${name}`);selected.add(name);for(const dependency of record.depends||[])visit(dependency.split(/\s+/)[0]);}
  visit('libgdal-core');visit('libpdal-core');visit('7zip');
  const destination=path.join(stage,'runtime','gis');await mkdir(path.join(destination,'conda-meta'),{recursive:true});
  const files=new Set();const origins=new Map();const packages=[];
  for(const name of [...selected].sort()){
    const record=records.get(name);packages.push({name,version:record.version,build:record.build,license:record.license,url:record.url,sha256:record.sha256,providedByOperatingSystem:name==='ucrt'});
    await writeFile(path.join(destination,'conda-meta',`${name}.json`),JSON.stringify(record,null,2)+'\n');
    if(name==='ucrt')continue;
    for(const filename of record.files||[]){
      const runtimeFile=windows?(/^(Library\/bin\/[^/]+\.dll|[^/]+\.dll)$/i.test(filename)||nativeTools.some(tool=>filename===`Library/bin/${tool}.exe`)||/^Library\/share\/(gdal|proj)\//.test(filename)||/^Library\/lib\/(gdalplugins|pdal)\/.*\.dll$/i.test(filename)):(/^lib\/.*\.so(?:\.[^/]*)?$/.test(filename)||nativeTools.some(tool=>filename===`bin/${tool}`)||/^share\/(gdal|proj)\//.test(filename));
      if(runtimeFile || (name==='7zip' && (/^(Library\/bin\/7z.*\.exe|bin\/7z(?:z|a)?|bin\/7z\.(?:exe|dll)|(?:lib|libexec)\/7zip\/.*)$/.test(filename)))){files.add(filename);origins.set(filename,name==='7zip'?decoder.directory:source);}
    }
  }
  for(const filename of files){const relative=path.normalize(filename);if(relative.startsWith('..')||path.isAbsolute(relative))throw new Error('Invalid native package member.');await mkdir(path.dirname(path.join(destination,relative)),{recursive:true});await cp(path.join(origins.get(filename),relative),path.join(destination,relative),{dereference:false,verbatimSymlinks:true});}
  const licenseDirectory=path.join(source,...(windows?['Library','share','licenses']:['share','licenses']));if(await access(licenseDirectory).then(()=>true,()=>false))await cp(licenseDirectory,path.join(destination,...(windows?['Library','share','licenses']:['share','licenses'])),{recursive:true});
  for(const tool of nativeTools)await access(path.join(destination,windows?'Library/bin':'bin',`${tool}${windows?'.exe':''}`));
  if(!await access(path.join(destination,windows?'bin/7z.exe':'bin/7z')).then(()=>true,()=>false)&&!await access(path.join(destination,windows?'Library/bin/7z.exe':'bin/7zz')).then(()=>true,()=>false))throw new Error('7-Zip runtime executable was not bundled.');
  await gisLicenses(stage,[...selected].map(name=>records.get(name)));
  await writeFile(path.join(stage,'THIRD-PARTY-GIS.json'),JSON.stringify(packages,null,2)+'\n');
  console.log(`Bundled ${selected.size} GIS runtime packages / ${files.size} native files.`);return packages;
}

async function gisLicenses(stage,records){
  let total=0;const sourceRoot=path.join(buildRoot,'gis-sources',targetLabel);await rm(sourceRoot,{recursive:true,force:true});await mkdir(sourceRoot,{recursive:true});
  for(const record of records){
    if(!record.url||!record.sha256)throw new Error(`Missing package integrity metadata: ${record.name}`);
    const basename=path.basename(new URL(record.url).pathname);
    const archive=await download(record.url,path.join(cache,'gis-packages',basename),record.sha256);
    let infoArchive=archive;
    if(basename.endsWith('.conda')){
      const directory=await unzipper.Open.file(archive);
      const member=directory.files.find(file=>/^info-.*\.tar\.zst$/.test(file.path));
      if(!member||member.uncompressedSize>32*1024*1024)throw new Error(`Invalid package metadata archive: ${record.name}`);
      infoArchive=path.join(cache,'gis-package-info',`${record.name}.tar`);await mkdir(path.dirname(infoArchive),{recursive:true});await writeFile(infoArchive,zstdDecompressSync(await member.buffer(),{maxOutputLength:64*1024*1024}));
    }
    const listing=await run('tar',['-tf',infoArchive],{capture:true});
    const members=listing.stdout.split(/\r?\n/).filter(filename=>/^info\/(licenses|recipe)\/.+/.test(filename)&&!filename.split('/').includes('..')&&!filename.includes('\\'));
    const licenseMembers=members.filter(filename=>filename.startsWith('info/licenses/')&&!filename.endsWith('/'));
    const directory=path.join(stage,'third-party','gis',record.name);await mkdir(directory,{recursive:true});
    if(members.length)await run('tar',['-xf',infoArchive,'-C',directory,...members],{capture:true});
    const runtime=(record.files||[]).some(filename=>/\.(dll|exe)$|\.so(?:\.[^/]*)?$|^(Library\/)?share\/(gdal|proj)/i.test(filename));
    let sourceFiles=[];
    if(record.name!=='ucrt'&&(!licenseMembers.length&&runtime||/\b[AL]?GPL|MPL|copyleft/i.test(record.license||''))){
      const recipeDirectory=path.join(directory,'info/recipe');
      const recipeFilename=['meta.yaml','rendered_recipe.yaml'].find(filename=>members.includes(`info/recipe/${filename}`));
      if(!recipeFilename)throw new Error(`Package source recipe not found: ${record.name}`);
      const parsedRecipe=parseYaml(await readFile(path.join(recipeDirectory,recipeFilename),'utf8'));const recipe=parsedRecipe.recipe||parsedRecipe;
      const sources=Array.isArray(recipe.source)?recipe.source:[recipe.source];
      for(const [index,source] of sources.entries()){
        if(!source)continue;const urls=Array.isArray(source.url)?source.url:[source.url];
        if(!urls[0]||!source.sha256)throw new Error(`Cannot verify corresponding source for ${record.name}.`);
        const name=path.basename(new URL(urls[0]).pathname);
        const candidates=[...new Set([...urls.map(url=>url.replace(/^http:/,'https:')),`https://sources.buildroot.net/${record.name}/${name}`,`https://distfiles.macports.org/${record.name}/${name}`])];let sourceArchive,url;const errors=[];
        for(const candidate of candidates){try{sourceArchive=await download(candidate,path.join(cache,'gis-sources',record.name,name),source.sha256);url=candidate;break;}catch(error){errors.push(error.message);}}
        if(!sourceArchive)throw new Error(`Cannot recover verified ${record.name} source: ${errors.join('; ')}`);
        const sourceDirectory=path.join(sourceRoot,record.name);await mkdir(sourceDirectory,{recursive:true});const sharedDirectory=path.join(sourceRoot,'archives');await mkdir(sharedDirectory,{recursive:true});const sharedFilename=`${source.sha256}-${name}`;if(!await access(path.join(sharedDirectory,sharedFilename)).then(()=>true,()=>false))await copyFile(sourceArchive,path.join(sharedDirectory,sharedFilename));sourceFiles.push({url,sha256:source.sha256,filename:`../archives/${sharedFilename}`});
        if(!licenseMembers.length){
          const sourceListing=await run('tar',['-tf',sourceArchive],{capture:true});
          const notices=sourceListing.stdout.split(/\r?\n/).filter(filename=>/(^|\/)(COPYING(?:\.[^/]*)?|LICENSE(?:\.[^/]*)?|COPYRIGHT(?:\.[^/]*)?|NOTICE(?:\.[^/]*)?)$/i.test(filename)&&!filename.split('/').includes('..')&&!filename.includes('\\'));
          if(notices.length){await run('tar',['-xf',sourceArchive,'-C',directory,...notices],{capture:true});licenseMembers.push(...notices);}
        }
      }
      await cp(path.join(directory,'info/recipe'),path.join(sourceRoot,record.name,'recipe'),{recursive:true});
