async function chooseArea(id) { if(id==='__sample'){$('#buffer').value=0;setBoundary(featureForBbox(sampleBbox));return;}if(id){const course=state.courses.find(item=>item.id===id);$('#buffer').value=course.bufferMeters??500;setBoundary(course.boundary);} }
function requestExtent() { const scope=$('input[name="scope"]:checked').value;if(scope==='source')return {scope};if(!state.boundary)throw new Error('Select a boundary, enter a bounding box, or choose the Ontario sample area.');return {scope,boundary:state.boundary,bufferMeters:Number($('#buffer').value)}; }
