async function loadPlan(id,offset=0,reset=true) {
  const plan=await api(`/api/discovery/${id}?offset=${offset}&limit=50`);state.plan=plan;state.planOffset=offset;if(reset)state.selected=new Set(plan.assetIds);localStorage.setItem('terrain.lastPlan',id);
