  $('#confirm-message').textContent=`Whole source / ${preset.products.map(product=>productNames[product]||product).join(' + ')} / native grids. Destination: ${destination}. Originals and extracted files are retained; allow disk space for both. Provider failures stop the job without discarding completed files.`;
