    if(!layer.selectionMarker){const title=layer.feature.properties.title||ids[0];const point=layer.feature.properties.checkboxPoint;
      const marker=L.marker(point?[point[1],point[0]]:layer.getBounds().getCenter(),{icon:L.divIcon({className:'map-selection-marker',iconSize:[28,28],iconAnchor:[14,14],html:`<label title="${escapeHtml(title)}"><input type="checkbox" data-select-map-asset="${escapeHtml(ids[0])}" aria-label="${escapeHtml(`Select ${title}`)}"></label>`}),bubblingMouseEvents:false});
      marker.on('add',()=>{const element=marker.getElement();L.DomEvent.disableClickPropagation(element);const input=element.querySelector('input');input.checked=ids.every(id=>state.selected.has(id));input.indeterminate=!input.checked;input.onchange=event=>setAssetSelection(ids,event.target.checked,true);});layer.selectionMarker=marker;marker.addTo(state.mapSelection);
