import { chromium } from 'playwright';
const browser=await chromium.launch({channel:'msedge',headless:true});
try {
  const page=await browser.newPage({viewport:{width:1440,height:1050}});
  const errors=[];page.on('pageerror',error=>errors.push(error.message));
  await page.goto('http://127.0.0.1:3123/');
  await page.waitForFunction(()=>document.querySelector('#connection-label')?.textContent==='Online');
  await page.evaluate(()=>localStorage.setItem('terrain.lastPlan','8b5e35dd-e32a-4440-8983-6cb39fffe2ec'));
  await page.reload();
  await page.waitForFunction(()=>document.querySelectorAll('[data-map-asset]').length>50&&!document.querySelector('.leaflet-zoom-anim'));
  if(await page.locator('[data-select-map-asset]').count()!==0)throw new Error('Saved plan automatically selected files');
  const desktop=await page.evaluate(()=>({viewport:{width:innerWidth,height:innerHeight},sections:document.querySelectorAll('[data-map-asset]').length,rows:document.querySelectorAll('[data-select-asset]').length,mapWidth:document.querySelector('#map').getBoundingClientRect().width,svgWidth:document.querySelector('.leaflet-plan-assets-pane svg').getBoundingClientRect().width,overflow:document.documentElement.scrollWidth>innerWidth}));
  const target=await page.evaluate(()=>{
    const bounds=document.querySelector('#map').getBoundingClientRect();
    for(const element of document.querySelectorAll('[data-map-asset]')){const shape=element.getBBox();for(const fractionX of [.5,.25,.75])for(const fractionY of [.5,.25,.75]){const point=new DOMPoint(shape.x+shape.width*fractionX,shape.y+shape.height*fractionY);if(!element.isPointInFill(point))continue;const screen=point.matrixTransform(element.getScreenCTM());if(screen.x>bounds.left+55&&screen.x<bounds.right-35&&screen.y>bounds.top+35&&screen.y<bounds.bottom-55)return {id:element.dataset.mapAsset,x:screen.x,y:screen.y};}}
    throw new Error('No visible coverage polygon contains an interactive point');
  });
  await page.mouse.click(target.x,target.y);await page.locator(`[data-select-map-asset="${target.id}"]`).waitFor();
  await page.screenshot({path:'data/map-selection-desktop.png',fullPage:true});
  const desktopSelection={markers:await page.locator('[data-select-map-asset]').count(),download:await page.locator('#download-plan').textContent(),selectedRows:await page.locator('[data-select-asset]:checked').count()};
  await page.locator(`[data-select-map-asset="${target.id}"]`).click();if(await page.locator('[data-select-map-asset]').count()!==0)throw new Error('Map checkbox did not deselect');
  await page.setViewportSize({width:390,height:844});await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));
  await page.screenshot({path:'data/map-selection-mobile.png',fullPage:true});
  const mobile=await page.evaluate(()=>({viewport:{width:innerWidth,height:innerHeight},sections:document.querySelectorAll('[data-map-asset]').length,overflow:document.documentElement.scrollWidth>innerWidth,map:document.querySelector('#map').getBoundingClientRect().toJSON()}));
  if(errors.length||desktop.overflow||mobile.overflow||desktop.sections<=50||desktop.svgWidth<desktop.mapWidth)throw new Error(JSON.stringify({errors,desktop,mobile}));
  console.log(JSON.stringify({desktop,desktopSelection,mobile,errors},null,2));
} finally {await browser.close();}
